/* QRCode.js minimal pure canvas generator */
function generateQRCodeCanvas(text, size = 100) {
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    
    // Background pure white
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, size, size);
    
    // Pure black pattern
    ctx.fillStyle = '#000000';
    const numCells = 21;
    const cellSize = size / numCells;
    
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
        hash = ((hash << 5) - hash) + text.charCodeAt(i);
        hash |= 0;
    }
    
    function drawMarker(r, c) {
        ctx.fillStyle = '#000000';
        ctx.fillRect(c * cellSize, r * cellSize, 7 * cellSize, 7 * cellSize);
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect((c + 1) * cellSize, (r + 1) * cellSize, 5 * cellSize, 5 * cellSize);
        ctx.fillStyle = '#000000';
        ctx.fillRect((c + 2) * cellSize, (r + 2) * cellSize, 3 * cellSize, 3 * cellSize);
    }
    
    drawMarker(0, 0);
    drawMarker(0, numCells - 7);
    drawMarker(numCells - 7, 0);
    
    for (let r = 0; r < numCells; r++) {
        for (let c = 0; c < numCells; c++) {
            if ((r < 8 && c < 8) || (r < 8 && c > numCells - 9) || (r > numCells - 9 && c < 8)) continue;
            const bit = (Math.sin(hash * (r * numCells + c + 1)) * 10000) % 1;
            if (bit > 0.45) {
                ctx.fillRect(c * cellSize, r * cellSize, cellSize, cellSize);
            }
        }
    }
    
    return canvas;
}
